    const name = (inst.name || '').split(' // ')[0].toLowerCase();
    const back = ((inst.name || '').split(' // ')[1] || '').toLowerCase(); // Hakka, Whispering Raven (Alrund's back face)
    const copied = (inst.copiedName || '').toLowerCase(); // Chameleon as a copy of Prowler
