    const wanted = new Set(s.zones.hand.flatMap(iid => String((s.cards[iid].bot || defOf(s.cards[iid].id) || {}).cost || (defOf(s.cards[iid].id) || {}).manaCost || '').match(/[WUBRG]/g) || []));
