    if (kind === 'scry') permanents(s).forEach(w => { const li = oracleLines(w, lastDefOf || (() => null)).map(l => NEAR.LOST_ISLE.exec(l)).find(Boolean); if (li) G.counter(s, w.iid, li[1].toLowerCase(), 1, { effect: true }); }); // Lost Isle Calling
    if (kind === 'scry' && away.length) permanents(s).filter(w => oracleLines(w, lastDefOf || (() => null)).some(l => NEAR.TEMPORAL_ANCHOR.test(l))).forEach(w => s.zones.library.slice(-away.length).forEach(iid => { G.move(s, iid, 'exile'); s.cards[iid].exiledWith = w.iid; s.cards[iid].playable = { forever: true }; })); // The Temporal Anchor (playable any turn)
    if (kind === 'scry') permanents(s).filter(w => w.nimTurn !== s.turn && oracleLines(w, lastDefOf || (() => null)).some(l => NEAR.NIMRODEL.test(l))).forEach(c => { c.nimTurn = s.turn; pumpBy(c, 1, 0); c.pump = { pow: 0, tou: 0, ...c.pump, kw: [...new Set([...((c.pump && c.pump.kw) || []), 'unblockable'])] }; }); // Nimrodel Watcher
    if (kind === 'scry') { const o = lastTables.find(t => t && t.zones && t !== s); if (o) permanents(s).filter(w => oracleLines(w, lastDefOf || (() => null)).some(l => NEAR.MARINER_SCRY.test(l))).forEach(() => permanents(o).filter(c => !G.isLand(c) && !c.tapped).sort((a, b) => worthOf(b, lastDefOf || (() => null)) - worthOf(a, lastDefOf || (() => null))).slice(0, top.length).forEach(c => { c.tapped = true; })); } // Elvish Mariner
    { const game = lastTables.find(t => t && t.bot); if (game) permanents(s).forEach(w => { const ss = oracleLines(w, lastDefOf || (() => null)).map(l => NEAR.SCRY_OR_SURVEIL.exec(l)).find(Boolean); if (ss) fireOn(game, s, w, `${kind}ed`, ss[1], s === game ? { other: game.bot && game.bot.s, defOf: lastDefOf } : null, lastDefOf || (() => null)); }); } // Matoya
