        const pt = exiled.power != null ? `${exiled.power}/${exiled.toughness}` : (inst.custom && inst.custom.pt) || null;
        const types = ((inst.typeLine || '').split(/\s+[—-]\s+/)[1] || '').split(/\s+/).filter(Boolean);
        if (pt) dup.imprint = { pt, types };
