    t = t.replace(/^(?:you may )?search your library for a basic land card or (?:a )?(?:cave|desert) card, (put it onto the battlefield tapped|reveal it), then shuffle(?: and put (?:that card|it) on top)?\.?$/i, (all, how) => (/reveal/i.test(how) ? 'search your library for a basic land card, reveal it, then shuffle and put that card on top' : 'search your library for a basic land card, put it onto the battlefield tapped, then shuffle')); // Scampering Surveyor, Compass Gnome, Silver Deputy
