    if ((m = /^other creatures you control have base power and toughness (\d+)\/(\d+) and are (\w+?)s in addition to their other creature types\.?$/i.exec(line))) return c => (self(c) ? null : { basePT: `${m[1]}/${m[2]}`, types: [m[3]] });
