    if ((m = /^prevent all combat damage that would be dealt to (.+?)\.?$/i.exec(line)) && isSelf(m[1], src)) return c => (self(c) ? { kws: [NO_COMBAT_DMG] } : null);
    // Shimmer Dragon: "As long as you control four or more artifacts, this creature has hexproof."; Paradise Druid: "… has hexproof as long as it's untapped."
    if ((m = /^as long as (.+?), (.+?) has (\w+)\.?$/i.exec(line)) && isSelf(m[2], src) && condition(null, m[1]) !== null && KEYWORDS.includes(m[3].toLowerCase())) return c => (self(c) && condition(s, m[1], { self: src, defOf, other }) ? { kws: [m[3].toLowerCase()] } : null);
    if ((m = /^(.+?) has (\w+) as long as it's untapped\.?$/i.exec(line)) && isSelf(m[1], src)) return c => (self(c) && !src.tapped ? { kws: [m[2].toLowerCase()] } : null);
    // Mesmerizing Benthid: "This creature has hexproof as long as you control an Illusion."
    if ((m = /^(.+?) has (\w+) as long as (.+?)\.?$/i.exec(line)) && isSelf(m[1], src) && condition(null, m[3]) !== null && KEYWORDS.includes(m[2].toLowerCase())) return c => (self(c) && condition(s, m[3], { self: src, defOf, other }) ? { kws: [m[2].toLowerCase()] } : null);
    // Aboshan's Desire: "Enchanted creature has shroud as long as there are seven or more cards in your graveyard."
    if ((m = /^enchanted creature has (\w+) as long as (.+?)\.?$/i.exec(line)) && condition(null, m[2]) !== null && KEYWORDS.includes(m[1].toLowerCase())) return c => (src.attachedTo && c.iid === src.attachedTo && condition(s, m[2], { self: src, defOf, other }) ? { kws: [m[1].toLowerCase()] } : null);
    // Scorpion Sentinel: "As long as you control seven or more lands, this creature gets +3/+0."
    if ((m = /^as long as (.+?), (.+?) gets \+(\d+)\/\+(\d+)\.?$/i.exec(line)) && isSelf(m[2], src) && condition(null, m[1]) !== null) return c => (self(c) && condition(s, m[1], { self: src, defOf, other }) ? { pow: Number(m[3]), tou: Number(m[4]) } : null);
    // Most Decrepit Old Bird: "This creature gets +1/+1 as long as there are seven or more cards in your graveyard."
    if ((m = /^(.+?) gets \+(\d+)\/\+(\d+) as long as (.+?)\.?$/i.exec(line)) && isSelf(m[1], src) && condition(null, m[4]) !== null) return c => (self(c) && condition(s, m[4], { self: src, defOf, other }) ? { pow: Number(m[2]), tou: Number(m[3]) } : null);
    // Way of the Thief: "Enchanted creature can't be blocked as long as you control a Gate."
    if ((m = /^enchanted creature can't be blocked as long as (.+?)\.?$/i.exec(line)) && condition(null, m[1]) !== null) return c => (src.attachedTo && c.iid === src.attachedTo && condition(s, m[1], { self: src, defOf, other }) ? { kws: ['unblockable'] } : null);
    // Trawler Drake: "This creature gets +1/+1 for each oil counter on it."
    if ((m = /^(.+?) gets \+1\/\+1 for each ([\w-]+) counter on it\.?$/i.exec(line)) && isSelf(m[1], src)) return c => { if (!self(c)) return null; const n = (src.counters || {})[m[2].toLowerCase()] || 0; return n ? { pow: n, tou: n } : null; };
    // Nimble Brigand: "This creature can't be blocked if you've committed a crime this turn."
    if ((m = /^(.+?) can't be blocked if (.+?)\.?$/i.exec(line)) && isSelf(m[1], src) && condition(null, m[2]) !== null) return c => (self(c) && condition(s, m[2], { self: src, defOf, other }) ? { kws: ['unblockable'] } : null);
    // Slippery Scoundrel: "As long as you have the city's blessing, this creature has hexproof and can't be blocked."
    if ((m = /^as long as (.+?), (.+?) has (\w+) and can't be blocked\.?$/i.exec(line)) && isSelf(m[2], src) && condition(null, m[1]) !== null && KEYWORDS.includes(m[3].toLowerCase())) return c => (self(c) && condition(s, m[1], { self: src, defOf, other }) ? { kws: [m[3].toLowerCase(), 'unblockable'] } : null);
    // Cephalid Inkmage: "This creature can't be blocked as long as there are seven or more cards in your graveyard."
    if ((m = /^(.+?) can't be blocked as long as (.+?)\.?$/i.exec(line)) && isSelf(m[1], src) && condition(null, m[2]) !== null) return c => (self(c) && condition(s, m[2], { self: src, defOf, other }) ? { kws: ['unblockable'] } : null);
    // Nightwhorl Hermit: "As long as there are seven or more cards in your graveyard, this creature gets +1/+0 and can't be blocked."
    if ((m = /^as long as (.+?), (.+?) gets \+(\d+)\/\+(\d+) and can't be blocked\.?$/i.exec(line)) && isSelf(m[2], src) && condition(null, m[1]) !== null) return c => (self(c) && condition(s, m[1], { self: src, defOf, other }) ? { pow: Number(m[3]), tou: Number(m[4]), kws: ['unblockable'] } : null);
    // Forsaken Monument: "Whenever you tap a permanent for {C}, add an additional {C}." (game.js's sourceOf)
    if (/^whenever you tap a permanent for \{C\}, add an additional \{C\}\.?$/i.test(line)) { s.extraC++; return () => null; }
