    if (G.isCreature(inst) && !inst.faceDown) { const st0 = stats(inst, factsOf(inst, defOf)); if (st0.pow === 1 && st0.tou === 1) { const sw = s.zones.graveyard.map(iid => s.cards[iid]).find(c => oracleLines(c, defOf).some(l => NEAR.SWORD_MEEK.test(l))); if (sw) { G.move(s, sw.iid, 'battlefield', { put: true }); G.attach(s, sw.iid, inst.iid, attachBonus(oracleText(sw, defOf))); } } }
    // Grifter's Blade: enters attached to your best creature
