    // Ulamog's Despoiler: two of the opponent's exiled cards to their graveyard for four +1/+1 counters
    if (has(NEAR.DESPOILER) && other && other.zones) { const ids = other.zones.exile.filter(iid => !other.cards[iid].exiledWith && !other.cards[iid].faceDown).slice(0, 2); if (ids.length === 2) { ids.forEach(iid => G.move(other, iid, 'graveyard')); G.counter(s, inst.iid, '+1/+1', 4, { effect: true }); } }
    // Ulamog, the Defiler: +1/+1 counters equal to the greatest mana value in exile
    if (has(NEAR.DEFILER_COUNTERS)) { const n = Math.max(0, ...[s, other].filter(t => t && t.zones).flatMap(t => t.zones.exile.map(iid => cmcOfInst(t.cards[iid], defOf)))); if (n) G.counter(s, inst.iid, '+1/+1', n, { effect: true }); }
