    if (attacks.length) attackedBy(game, s, attacks.map(x => game.cards[typeof x === 'string' ? x : x.iid]), defOf, null); // Opp's Marchesa's Decree
    refreshGrants(game, defOf);
    // "Whenever this attacks" triggers, exalted, battle cry, annihilator; tokens that enter attacking
    // go after the same player or planeswalker.
    const list = attacks.map(x => (typeof x === 'string' ? { iid: x } : x));
    const joined = declareAttack(game, list.map(a => game.cards[a.iid]), defOf, {
      sacrifice: (n, why) => oppSacrifices(game, n, why), game, ctx: { hitOpps: n => { game.oppLife -= n; } },
      info: inst => ({ player: !(list.find(a => a.iid === inst.iid) || {}).pw }),
    })
      .map(([from, iid]) => ({ iid, pw: (list.find(a => a.iid === from) || {}).pw }));
    attacks = list.concat(joined);
    let attackers = attacks.map(x => (typeof x === 'string' ? { iid: x } : x))
      .map(x => ({ inst: game.cards[x.iid], pw: x.pw && s.cards[x.pw] && s.cards[x.pw].zone === 'battlefield' ? s.cards[x.pw] : null }))
      .filter(a => a.inst && a.inst.zone === 'battlefield')
      .map(a => Object.assign(a, { st: stats(a.inst, defOf(a.inst.id)) }))
      .sort((a, b) => hitOf(b.st) - hitOf(a.st));
    // Opp's instants when you attack: removal on an attacker, before blocks.
    const answered = oppInstantAt(game, defOf, 'attack', attackers);
    attackers = attackers.filter(a => a.inst.zone === 'battlefield');
    // uses: how many attackers it can still block (Brave the Sands gives each one more).
    // Void Winnower (yours): "Your opponents can't block with creatures with even mana values."
    const winnowed = winnows(game, WINNOW_BLOCK, defOf);
    const free = creatures(s, c => !c.tapped && !(winnowed && cmcOfInst(c, defOf) % 2 === 0)).map(inst => ({ inst, st: botStats(inst), uses: blocksAllowed(s, inst, defOf) }));
    // Mirri attacking (or Silent Arbiter): only so many of Opp's creatures can block.
    const limit = blockRules(botRules(game, defOf).all, attackers.map(a => a.inst), defOf);
    if (limit.why) G.log(game, `${limit.why[0].toUpperCase()}${limit.why.slice(1)}.`);
    let blocks = pickBlocks(attackers, free, game.oppLife, Math.min(limit.cap, blockersAffordable(s, limit.tax)), s);
    // Archangel of Tithes: Opp pays for each of its blockers.
    const blockerCount = new Set([...blocks.values()].flat().map(b => b.inst)).size;
    if (limit.tax && blockerCount) { onOpp(game, () => G.autoPay(s, `{${limit.tax * blockerCount}}`)); G.log(game, `Opp paid {${limit.tax * blockerCount}} to block.`); }
    // Berserker's Frenzy: Opp's creatures must block this turn (all), or block the way you'd choose (worst).
    const forced = s.forcedBlock && s.forcedBlock.turn === game.turn ? s.forcedBlock : null;
    if (forced) blocks = forcedBlocks(attackers, free, forced.worst ? new Map() : blocks, forced, s);
    // Peema Aether-Seer: "Target creature blocks this turn if able."
    const must = free.filter(b => b.inst.mustBlock === game.turn);
    if (must.length) blocks = forcedBlocks(attackers, must, blocks, {}, s);
    // Treeshaker Chimera, Noble Quarry: "All creatures able to block this creature do so." (its unassigned blockers go to it)
    const lured = attackers.filter(a => !a.pw && a.st.kw.has('lure'));
    if (lured.length) {
      const busy = new Set([...blocks.values()].flat().map(b => b.inst));
      for (const b of free.filter(f => !busy.has(f.inst))) { const a = lured.find(x => canBlock(b.st, x.st, s)); if (a) blocks.set(a, [...(blocks.get(a) || []), b]); }
    }

